def match(orders):
    import heapq

    book = {}  # id -> dict(side, price, qty, arrival)
    buy_heap = []   # entries: (-price, arrival, id)
    sell_heap = []  # entries: (price, arrival, id)
    trades = []
    arrival_counter = 0

    def push_order(o):
        if o['side'] == 'buy':
            heapq.heappush(buy_heap, (-o['price'], o['arrival'], o['id']))
        else:
            heapq.heappush(sell_heap, (o['price'], o['arrival'], o['id']))

    def top_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            if oid in book and book[oid]['qty'] > 0:
                return item
            heapq.heappop(heap)
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty
        arrival = arrival_counter
        arrival_counter += 1

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            top = top_valid(opp_heap)
            if top is None:
                break
            resting_id = top[2]
            resting = book[resting_id]
            resting_price = resting['price']

            if typ != 'market':
                if side == 'buy' and price < resting_price:
                    break
                if side == 'sell' and price > resting_price:
                    break

            trade_qty = min(remaining, resting['qty'])
            if side == 'buy':
                trades.append([oid, resting_id, resting_price, trade_qty])
            else:
                trades.append([resting_id, oid, resting_price, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] == 0:
                del book[resting_id]
                heapq.heappop(opp_heap)
            # else: partially filled resting order keeps its place; leave heap as-is

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'arrival': arrival}
            push_order({'side': side, 'price': price, 'id': oid, 'arrival': arrival})

    return trades

